<?php
require __DIR__.'/includes/security.php';
session_name('cyber_admin');session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();header('Cache-Control: no-store');
$_SESSION['csrf']=$_SESSION['csrf']??bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='GET'&&!empty($_SESSION['admin'])){header('Location: index.php');exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf'])){security_event('csrf_failed','');http_response_code(403);exit('Invalid request');}
 if(isset($_POST['logout'])){$_SESSION=[];session_destroy();header('Location: admin.php');exit;}
 $ip=$_SERVER['REMOTE_ADDR']??'';$q=security_db()->prepare("SELECT COUNT(*) FROM security_events WHERE event_type='admin_login_failed' AND source_ip=? AND occurred_at>=NOW()-INTERVAL 5 MINUTE");$q->execute([$ip]);
 $admin=security_db()->query('SELECT * FROM security_admin WHERE id=1')->fetch(PDO::FETCH_ASSOC);
 if($q->fetchColumn()<5 && is_string($_POST['username']??null)&&is_string($_POST['password']??null)&&$_POST['username']===$admin['username']&&password_verify($_POST['password'],$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin']=1;security_event('admin_login_success','cyber');header('Location: index.php');exit;}
 security_event('admin_login_failed','cyber');$error='Invalid credentials or too many attempts. After five failures, wait five minutes.';
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Security administrator login</title><link rel="stylesheet" href="assets/admin-login.css"></head><body><main class="admin-login-shell"><section class="admin-login-brand"><a class="brand" href="index.php"><span class="brand-mark">P</span><span><b>PLMUN</b><small>CYBER WATCH</small></span></a><div class="brand-message"><span class="eyebrow">SECURITY OPERATIONS</span><h1>Protecting the student portal.</h1><p>Sign in to review security events, investigate incidents, and monitor portal health.</p></div><div class="brand-status"><i></i> Monitoring workspace</div></section><section class="admin-login-card"><span class="eyebrow">ADMINISTRATOR ACCESS</span><h2>Welcome back</h2><p>Enter your security administrator credentials to continue.</p><?php if($error):?><div class="admin-login-error" role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><form action="admin.php" method="post" id="admin-login-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf'],ENT_QUOTES,'UTF-8')?>"><label for="admin-username">Username</label><input id="admin-username" name="username" autocomplete="username" placeholder="Enter username" required autofocus><label for="admin-password">Password</label><input id="admin-password" type="password" name="password" autocomplete="current-password" placeholder="Enter password" required><button id="admin-login-submit" type="submit">Sign in to Cyber Watch</button></form><div class="admin-login-foot"><span>Restricted to authorized security administrators</span><a href="student-portal/login.php">Student portal</a></div></section></main><script>document.getElementById('admin-login-form').addEventListener('submit',()=>{const button=document.getElementById('admin-login-submit');button.disabled=true;button.textContent='Signing in...';});window.addEventListener('pageshow',()=>{const button=document.getElementById('admin-login-submit');button.disabled=false;button.textContent='Sign in to Cyber Watch';});</script></body></html>
